import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageStudents() {
  const [students, setStudents] = useState([]);
  const [availableSubjects, setAvailableSubjects] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  
  const [formData, setFormData] = useState({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' });

  const fetchStudents = () => axios.get('http://localhost:8081/api/view-students').then(res => setStudents(res.data));
  const fetchSubjects = () => axios.get('http://localhost:8081/api/view-subjects').then(res => setAvailableSubjects(res.data));

  useEffect(() => { fetchStudents(); fetchSubjects(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const apiPath = isEditing ? `http://localhost:8081/api/update-student/${editId}` : 'http://localhost:8081/api/add-student';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") alert("Error: " + res.data.error);
        else { fetchStudents(); resetForm(); }
    }).catch(() => alert("Error!"));
  };

  const handleEdit = (s) => {
    setIsEditing(true); setEditId(s.id);
    setFormData({ name: s.name, grade: s.grade, subjects: s.subjects || '', phone_number: s.phone_number, address: s.address || '' });
    setShowForm(true);
  };

  const resetForm = () => { setShowForm(false); setIsEditing(false); setEditId(null); setFormData({ name: '', username: '', grade: 'Grade 10', subjects: '', phone_number: '', address: '', password: 'ST@123' }); };

  const filteredStudents = students.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh', animation: 'fadeIn 0.5s' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#fff', padding: '20px 30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '25px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', display: 'flex', alignItems: 'center', gap: '10px' }}>👨‍🎓 Manage Students</h2>
        <div style={{ display: 'flex', gap: '15px' }}>
          <input type="text" placeholder="Search Student..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
          <button onClick={() => {resetForm(); setShowForm(true);}} style={styles.primaryBtn}>+ Register Student</button>
        </div>
      </div>

      <div style={styles.tableContainer}>
        <table style={styles.table}>
          <thead>
            <tr style={{ backgroundColor: '#f1f5f9' }}>
              <th style={styles.th}>Full Name</th><th style={styles.th}>Grade</th><th style={styles.th}>Enrolled Subjects</th><th style={styles.th}>Contact Details</th><th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredStudents.map(s => (
              <tr key={s.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{...styles.td, fontWeight: 'bold', color: '#15803d'}}>{s.name}</td>
                <td style={{...styles.td, color: '#64748b'}}>{s.grade}</td>
                <td style={{...styles.td, color: '#0369a1', fontWeight: 'bold'}}>{s.subjects || '-'}</td>
                <td style={{...styles.td, color: '#475569'}}>📞 {s.phone_number}<br/><span style={{fontSize: '12px'}}>📍 {s.address || 'N/A'}</span></td>
                <td style={styles.td}><button onClick={() => handleEdit(s)} style={styles.editBtn}>✏️ Edit</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={styles.modalTitle}>{isEditing ? '✏️ Edit Student Details' : '➕ Register New Student'}</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Student Full Name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required style={styles.input} />
              
              {!isEditing && (
                <>
                  <input type="text" placeholder="Login Username" value={formData.username} onChange={e => setFormData({...formData, username: e.target.value})} required style={styles.input} />
                  <input type="text" placeholder="Default Password (ST@123)" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} required style={styles.input} />
                </>
              )}

              <input type="text" placeholder="Grade (e.g. Grade 10)" value={formData.grade} onChange={e => setFormData({...formData, grade: e.target.value})} required style={styles.input} />
              
              {!isEditing && (
                <div style={{ padding: '10px', border: '1px solid #cbd5e1', borderRadius: '8px' }}>
                  <p style={{ margin: '0 0 10px 0', fontSize: '13px', color: '#64748b' }}>Select Subjects (Comma separated logic applied automatically):</p>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
                    {availableSubjects.map(sub => (
                      <label key={sub.id} style={{ fontSize: '13px', color: '#333', display: 'flex', alignItems: 'center', gap: '5px' }}>
                        <input 
                          type="checkbox" 
                          onChange={(e) => {
                            let curr = formData.subjects ? formData.subjects.split(', ') : [];
                            if(e.target.checked) curr.push(sub.subject_name);
                            else curr = curr.filter(x => x !== sub.subject_name);
                            setFormData({...formData, subjects: curr.join(', ')});
                          }}
                        /> {sub.subject_name}
                      </label>
                    ))}
                  </div>
                </div>
              )}

              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} required style={styles.input} />
              <input type="text" placeholder="Home Address" value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} style={styles.input} />

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>{isEditing ? 'Update Details' : 'Register Student'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  searchInput: { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', width: '250px' },
  primaryBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  tableContainer: { backgroundColor: '#fff', borderRadius: '15px', overflowX: 'auto', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
  th: { padding: '18px 20px', color: '#475569', fontWeight: 'bold', fontSize: '14px', borderBottom: '2px solid #e2e8f0' },
  td: { padding: '15px 20px', fontSize: '14px' },
  editBtn: { padding: '6px 12px', backgroundColor: '#f1f5f9', color: '#0369a1', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000, backdropFilter: 'blur(4px)' },
  modal: { backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '450px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' },
  modalTitle: { margin: '0 0 20px 0', color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' },
  input: { padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '14px' },
  cancelBtn: { padding: '10px 20px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' },
  saveBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }
};
